#!/usr/bin/env node
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
const sourcePath = resolve(root, "design-tokens/source-figma-export.json");
const outputDirectory = resolve(root, "src/tokens/generated");
const legacyIdPrefix = "26:";
const legacyFirstPrimitiveId = 11;

const generatedHeader = `/* Generated from design-tokens/source-figma-export.json.
 * Do not edit this file directly. Run npm run tokens:build.
 */`;

function cssName(value) {
  return value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function cssNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number))
    throw new Error(`Invalid numeric token: ${value}`);
  return number;
}

function dimensionValue(collection, variable, value) {
  const number = cssNumber(value);
  if (collection === "5 · Opacity") return String(number / 100);
  if (variable.name.startsWith("font/weight/")) return String(number);
  if (
    collection === "2 · Spacing" ||
    collection === "3 · Radius" ||
    collection === "4 · Border" ||
    variable.name.startsWith("font/size/") ||
    variable.name.startsWith("font/tracking/")
  ) {
    return number === 0 ? "0" : `${number}px`;
  }
  return String(number);
}

function stringValue(variable, value) {
  if (variable.name.startsWith("font/family/") && value === "Manrope") {
    return '"Manrope Variable", Arial, sans-serif';
  }
  return JSON.stringify(value);
}

function collection(source, name) {
  const result = source.collections?.[name];
  if (!result) throw new Error(`Missing Figma collection: ${name}`);
  return result;
}

function validateSource(source) {
  const variables = Object.values(source.collections || {}).flatMap(
    (item) => item.variables || [],
  );
  if (variables.length !== source.totalVariables) {
    throw new Error(
      `Figma export declares ${source.totalVariables} variables but contains ${variables.length}`,
    );
  }
  for (const [collectionName, item] of Object.entries(source.collections)) {
    const names = new Set();
    for (const variable of item.variables) {
      if (names.has(variable.name)) {
        throw new Error(`Duplicate token ${collectionName}/${variable.name}`);
      }
      names.add(variable.name);
      for (const mode of item.modes) {
        if (!(mode in variable.values)) {
          throw new Error(
            `Missing ${mode} value for ${collectionName}/${variable.name}`,
          );
        }
      }
    }
  }
  return variables.length;
}

function createVariableIndex(source) {
  const index = new Map();
  for (const item of Object.values(source.collections)) {
    for (const variable of item.variables) {
      if (variable.id) index.set(variable.id, variable);
    }
  }

  let usesLegacyBridge = false;
  const primitives = collection(source, "_Colors Primitives").variables;
  if (!primitives.some((variable) => variable.id)) {
    usesLegacyBridge = true;
    primitives.forEach((variable, offset) => {
      index.set(
        `${legacyIdPrefix}${legacyFirstPrimitiveId + offset}`,
        variable,
      );
    });
  }
  return { index, usesLegacyBridge };
}

function resolveColor(value, variableIndex) {
  if (/^#[0-9a-f]{6,8}$/i.test(value) || /^rgba?\(/i.test(value)) {
    return value;
  }
  const alias = /^\{VariableID:([^}]+)\}$/.exec(value);
  if (!alias) throw new Error(`Unsupported color value: ${value}`);
  const primitive = variableIndex.get(alias[1]);
  if (!primitive) throw new Error(`Unresolved Figma alias: ${alias[1]}`);
  const resolved = primitive.values.Default;
  if (!resolved)
    throw new Error(`Alias ${alias[1]} does not point to a primitive`);
  return resolved;
}

function declaration(name, value) {
  return `  --${name}: ${value};`;
}

function renderBlock(selectors, declarations) {
  return `${selectors.join(",\n")} {\n${declarations.join("\n")}\n}`;
}

export function buildTokenFiles(source) {
  const totalVariables = validateSource(source);
  const { index: variableIndex, usesLegacyBridge } =
    createVariableIndex(source);
  const primitives = collection(source, "_Colors Primitives").variables;
  const white = collection(source, "White").variables;
  const semantic = collection(source, "1 · Semantic Colors").variables;

  let resolvedAliasCount = 0;
  const colorDeclarations = [...primitives, ...white].map((variable) => {
    const mode = variable.values.Default ? "Default" : "Mode 1";
    return declaration(
      `color-${cssName(variable.name)}`,
      variable.values[mode],
    );
  });

  const semanticModes = Object.fromEntries(
    ["Light", "Dark"].map((mode) => [
      mode,
      semantic.map((variable) => {
        resolvedAliasCount += 1;
        return declaration(
          `color-${cssName(variable.name)}`,
          resolveColor(variable.values[mode], variableIndex),
        );
      }),
    ]),
  );

  const dimensionCollections = [
    "2 · Spacing",
    "3 · Radius",
    "4 · Border",
    "5 · Opacity",
    "6 · Typography",
  ];
  const dimensionDeclarations = dimensionCollections.flatMap((collectionName) =>
    collection(source, collectionName).variables.map((variable) => {
      const value = variable.values.Default;
      const normalized =
        variable.type === "STRING"
          ? stringValue(variable, value)
          : dimensionValue(collectionName, variable, value);
      return declaration(cssName(variable.name), normalized);
    }),
  );

  const files = {
    "colors.css": `${generatedHeader}\n\n${renderBlock([":root"], colorDeclarations)}\n`,
    "dimensions.css": `${generatedHeader}\n\n${renderBlock([":root"], dimensionDeclarations)}\n`,
    "semantic-colors.css": `${generatedHeader}\n\n${renderBlock(
      [":root", '[data-theme="light"]'],
      semanticModes.Light,
    )}\n\n${renderBlock(['[data-theme="dark"]'], semanticModes.Dark)}\n`,
    "index.css": `${generatedHeader}\n\n@import "./colors.css";\n@import "./dimensions.css";\n@import "./semantic-colors.css";\n`,
  };

  return {
    files,
    report: {
      totalVariables,
      primitiveColors: primitives.length + white.length,
      semanticColors: semantic.length,
      resolvedAliasCount,
      dimensionTokens: dimensionDeclarations.length,
      usesLegacyBridge,
    },
  };
}

export async function loadTokenSource(path = sourcePath) {
  return JSON.parse(await readFile(path, "utf8"));
}

async function run() {
  const check = process.argv.includes("--check");
  const source = await loadTokenSource();
  const { files, report } = buildTokenFiles(source);
  await mkdir(outputDirectory, { recursive: true });

  for (const [name, content] of Object.entries(files)) {
    const path = resolve(outputDirectory, name);
    if (check) {
      let current;
      try {
        current = await readFile(path, "utf8");
      } catch {
        throw new Error(`Missing generated token file: ${name}`);
      }
      if (current !== content) {
        throw new Error(`${name} is stale. Run npm run tokens:build.`);
      }
    } else {
      await writeFile(path, content, "utf8");
    }
  }

  const action = check ? "verified" : "generated";
  console.log(
    `Design tokens ${action}: ${report.totalVariables} variables, ` +
      `${report.semanticColors} semantic colors, ${report.resolvedAliasCount} resolved aliases.`,
  );
  if (report.usesLegacyBridge) {
    console.log(
      "Using the validated legacy VariableID bridge; replace it when the Figma export includes IDs.",
    );
  }
}

if (resolve(process.argv[1] || "") === fileURLToPath(import.meta.url)) {
  run().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
  });
}
